mapper.select:
SELECT t.*, s.scene_name FROM task_info t
LEFT JOIN scene_info s ON t.scene_id = s.id
WHERE t.deleted = 0

    AND t.task_name LIKE CONCAT('%', #{taskName}, '%')


    AND t.scene_id = #{sceneId}


    AND t.status = #{status}


    AND t.priority = #{priority}

ORDER BY t.priority DESC, t.created_at DESC

mapper.update:
UPDATE task_info
status = #{status}, actual_start_time = #{actualStartTime}, actual_end_time = #{actualEndTime}, updated_by = #{updatedBy}, updated_at = NOW()
WHERE id = #{id}
